<script setup>import {ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {ShoppingBag,ShoppingCart,UserRound,Menu,X,LogOut} from 'lucide-vue-next';import {useStore} from '@/stores/shop.js';const s=useStore(),route=useRoute(),router=useRouter(),open=ref(false);watch(()=>route.fullPath,()=>open.value=false);function logout(){s.logout();router.push('/')}</script><template><header class="site-header"><div class="container header-inner"><RouterLink to="/" class="brand"><span class="brand-icon"><ShoppingBag :size="22"/></span> ShopNest<span class="brand-dot">.</span></RouterLink><nav class="desktop-links" aria-label="Primary navigation"><RouterLink to="/">Home</RouterLink><RouterLink to="/catalog">Shop</RouterLink><RouterLink v-if="s.user?.role==='customer'" to="/dashboard">My account</RouterLink><RouterLink v-if="s.user?.role==='admin'" to="/admin">Admin dashboard</RouterLink></nav><div class="header-actions"><RouterLink to="/cart" class="header-icon" :aria-label="'Cart, '+s.cartCount+' items'"><ShoppingCart :size="21"/><span v-if="s.cartCount" class="cart-badge">{{s.cartCount}}</span></RouterLink><RouterLink v-if="!s.user" to="/login" class="header-icon account-icon" aria-label="Sign in"><UserRound :size="21"/></RouterLink><button v-else class="header-icon account-icon" aria-label="Sign out" title="Sign out" @click="logout"><LogOut :size="21"/></button><button class="header-icon mobile-toggle" :aria-expanded="open" aria-controls="mobile-nav" :aria-label="open?'Close menu':'Open menu'" @click="open=!open"><X v-if="open" :size="23"/><Menu v-else :size="23"/></button></div></div><nav v-if="open" id="mobile-nav" class="mobile-links" aria-label="Mobile navigation"><RouterLink to="/">Home</RouterLink><RouterLink to="/catalog">Shop all</RouterLink><RouterLink to="/cart">Cart ({{s.cartCount}})</RouterLink><RouterLink v-if="s.user?.role==='customer'" to="/dashboard">My account</RouterLink><RouterLink v-if="s.user?.role==='customer'" to="/orders">Purchase history</RouterLink><RouterLink v-if="s.user?.role==='admin'" to="/admin">Admin dashboard</RouterLink><RouterLink v-if="!s.user" to="/login">Sign in</RouterLink><RouterLink v-if="!s.user" to="/signup">Create account</RouterLink></nav></header></template>